def centre_cible(points):
    """Renvoie (moyenne des x, moyenne des y), arrondies à 2 décimales."""
    somme_x = 0
    somme_y = 0
    for x, y in points:
        somme_x += x
        somme_y += y
    nombre = len(points)
    return (round(somme_x / nombre, 2), round(somme_y / nombre, 2))

